import {matchQuestions,recommendTeams,validateMatchData,metricLabels,formatMatchMetric} from './team-match.js';
import {markSVG} from './club-gallery.js';
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=n=>Number(n).toLocaleString('zh-CN');
export function setupQuiz({stadiums,dialog,onOpen,closeDialog,onStart=()=>{}}){
 const content=document.querySelector('#quiz-content');let step=0,answers={},data=null,promise=null,session=0;
 const period=()=>data.metadata.periodZh||data.metadata.period||'数据时间范围见来源说明';
 function methodology(){return `<details class="match-method"><summary>数据从哪里来，怎样推荐？ <span>＋</span></summary><div><p>数据来自 ${escape(data.metadata.sourceName||'Football-Data.co.uk')}，共采集 ${number(data.metadata.totalMatches)} 场联赛记录${data.metadata.clubInvolvedUniqueMatches?'，其中 '+number(data.metadata.clubInvolvedUniqueMatches)+' 场涉及本站的球队':''}。统计范围：${escape(period())}。</p><p>欧洲按完整赛季，南美按自然年；巴西包含疫情导致的跨年场次，阿根廷保留来源收录的阶段及联赛杯式赛制场次。主客场按数据中的主客队身份统计，不代表比赛必然在本页展示的球场举行。</p><p>将你选择的方向，与本库 24 支主队的同类比赛统计分位比较；每道有偏好的题等权，不设偏好的题不计分。结果是可解释的观赛偏好匹配，问题与权重由本站设计，未经过球迷偏好数据的训练或准确率验证。</p><p>只比较国内联赛中的表现频率，不能据此排列跨联赛实力。进球数不等同于进攻战术，零封比例不等同于防守能力；数据也不能决定你最终会爱上哪支球队。圣西罗按 AC 米兰、马拉卡纳按弗拉门戈统计。</p><p class="match-method-links"><a href="https://www.football-data.co.uk/data.php" target="_blank" rel="noopener noreferrer">原始数据与字段说明 ↗</a><a href="assets/club-match-data.json" target="_blank" rel="noopener">本站统计快照 ↗</a></p></div></details>`;}
 function focusTitle(){const title=content.querySelector('#quiz-title');title.tabIndex=-1;title.focus({preventScroll:true});dialog.scrollTop=0;}
 function render(){
  delete content.dataset.matchMode;const q=matchQuestions[step];content.innerHTML=`<p class="quiz-step">FIND YOUR CLUB / ${String(step+1).padStart(2,'0')} OF 04</p><div class="quiz-progress" role="progressbar" aria-label="答题进度" aria-valuemin="0" aria-valuemax="4" aria-valuenow="${step+1}"><i style="width:${(step+1)/4*100}%"></i></div><div class="match-data-badge"><i></i> ${number(data.metadata.clubInvolvedUniqueMatches||data.metadata.totalMatches)} 场候选球队比赛 · 24 支主队</div><h2 class="quiz-heading" id="quiz-title">${q.title}</h2><p class="quiz-description">${q.description}</p><div class="quiz-options">${q.options.map((o,i)=>`<button class="quiz-option ${answers[q.id]===o.id?'is-answered':''}" data-answer="${o.id}" aria-pressed="${answers[q.id]===o.id}"><span>0${i+1}</span><div><strong>${o.title}</strong><small>${o.detail}</small></div><b>↗</b></button>`).join('')}</div><div class="match-question-footer">${step?'<button class="quiz-back" data-quiz-back>← 上一题</button>':'<span>约 1 分钟，跟着你的观赛偏好选择。</span>'}<small>答案仅在本页计算</small></div>${methodology()}`;focusTitle();
 }
 function result(){
  const result=recommendTeams(answers,data,stadiums),personal=result.mode==='matched';
  content.innerHTML=`<p class="quiz-step">YOUR NEXT CLUB / 比赛数据 × 你的偏好</p><h2 class="quiz-heading" id="quiz-title">${personal?'这三支，值得先认识一下。':'先认识三种不同的比赛风格。'}</h2><p class="quiz-description">${personal?'按你设定的 '+result.preferenceCount+' 项观赛偏好，选出统计表现更接近的球队。':'你暂时没有设定明确偏好。下面是三种数据特征鲜明的探索起点，并非个性化推荐。'}</p><div class="match-results">${result.picks.map((pick,i)=>{const s=pick.stadium,p=pick.profile;return `<article class="match-team ${i===0?'is-first':''}" style="--club-colour:${s.color}"><div class="match-team-heading"><span class="match-result-mark">${markSVG(s)}</span><div><p>${i===0?(personal?'先从这里开始':'探索起点 01'):'也可以认识 / 0'+(i+1)}</p><h3>${escape(s.club.split(' / ')[0])}</h3><small>${escape(s.city)} · ${escape(s.league)} · 样本 ${number(p.matches)} 场</small></div><button data-quiz-open="${s.id}" aria-label="认识${escape(s.club)}，进入${escape(s.name)}">认识球队 ↗</button></div><ul>${pick.evidence.map(e=>`<li><span>${escape(e.choice)}</span><strong>${metricLabels[e.metric]} <b>${formatMatchMetric(e.metric,e.raw)}</b></strong></li>`).join('')}</ul></article>`;}).join('')}</div><p class="match-result-note">统计截止范围：${escape(period())}。这是认识球队的起点，喜欢可以慢慢发生。</p><div class="quiz-result-actions"><button class="text-link" data-quiz-restart>换一组偏好，再看看 ↻</button></div>${methodology()}`;content.dataset.matchMode=result.mode;focusTitle();
 }
 async function load(){
  const token=++session;content.innerHTML='<p class="quiz-step">FIND YOUR CLUB</p><h2 class="quiz-heading" id="quiz-title">用真实比赛，<br>认识一支球队。</h2><p class="quiz-description" role="status">正在读取比赛统计…</p>';focusTitle();
  try{promise??=fetch('./assets/club-match-data.json').then(r=>{if(!r.ok)throw Error('读取失败');return r.json();}).then(d=>validateMatchData(d,stadiums));data=await promise;if(token!==session||!dialog.open)return;step=0;answers={};render();}
  catch{promise=null;if(token!==session||!dialog.open)return;content.innerHTML='<h2 class="quiz-heading" id="quiz-title">比赛数据暂时没有连接上。</h2><p class="quiz-description">请重试，读取数据后再开始匹配。</p><button class="button lime" data-quiz-retry>重新读取 ↻</button>';focusTitle();}
 }
 content.addEventListener('click',e=>{const option=e.target.closest('[data-answer]');if(option&&data){const q=matchQuestions[step];if(!q.options.some(o=>o.id===option.dataset.answer))return;answers[q.id]=option.dataset.answer;if(step<matchQuestions.length-1){step++;render();}else result();}if(e.target.closest('[data-quiz-back]')&&step>0){step--;render();}if(e.target.closest('[data-quiz-restart]')){step=0;answers={};render();}if(e.target.closest('[data-quiz-retry]'))load();const go=e.target.closest('[data-quiz-open]');if(go){closeDialog(dialog,true);onOpen(go.dataset.quizOpen);}});
 dialog.addEventListener('close',()=>{session++;});
 return()=>{onStart();if(!dialog.open)dialog.showModal();load();};
}
